"use client";
import type { MouseEvent, ReactNode } from "react";
import { Ellipsis, ChevronRight as NavArrowRight } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { DropdownMenuContent, DropdownMenuItem, DropdownMenuRoot, DropdownMenuTrigger } from "../dropdown-menu/dropdown-menu";
import { SiliconLink } from "../lib/silicon-provider";
import { motionTokens } from "../lib/motion-tokens";
import styles from "./breadcrumb.module.css";
export interface BreadcrumbItem {
  label: string;
  href?: string;
  /** Runs when the crumb is chosen. Without an href the crumb renders as a button, for paths that live in local state. */
  onClick?: (event: MouseEvent<HTMLElement>) => void;
}
export interface BreadcrumbProps {
  /** The path from the top level to the current page, which is the last item. */
  items: BreadcrumbItem[];
  /** The navigation landmark's name (default "Breadcrumb"). */
  ariaLabel?: string;
  /** Experimental. The most crumbs to show, at least 2. A longer path shows the first crumb, a "…" menu of the levels
   *  between, and the last `maxItems - 1` crumbs. By default the path never collapses. */
  maxItems?: number;
}
/** Crumbs present on first render stay still; crumbs added later slide in from the path before them.
 *  With maxItems, the levels a long path hides move into a "…" menu, where they stay links. */
export function Breadcrumb({ items, ariaLabel = "Breadcrumb", maxItems }: BreadcrumbProps) {
  const reduced = useReducedMotion() ?? false;
  const still = { duration: 0 };
  const path = items.map(item => item.label).join("/");
  // The first crumb and the current page always show. Crumbs keep their index in `items` as their key, so the ones
  // that stay visible never remount when the path collapses or grows.
  const shown = Math.max(2, Math.floor(maxItems ?? Infinity));
  const hidden = items.length > shown ? items.slice(1, items.length - shown + 1) : [];
  const crumb = (key: string, first: boolean, children: ReactNode) => <motion.li key={key}
    layout={reduced ? false : "position"} layoutDependency={path}
    initial={reduced ? false : { opacity: 0, x: -8, filter: `blur(${motionTokens.blur.subtle}px)` }} animate={{ opacity: 1, x: 0, filter: "blur(0px)" }}
    exit={reduced ? { opacity: 0, transition: still } : { opacity: 0, x: -4, filter: `blur(${motionTokens.blur.subtle}px)`, transition: { duration: motionTokens.duration.instant, ease: [...motionTokens.ease.standard] } }}
    transition={reduced ? still : { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter], layout: motionTokens.spring.smooth }}>
    {!first && <NavArrowRight width={14} height={14} aria-hidden="true"/>}
    {children}
  </motion.li>;
  const crumbs = items.map((item, index) => {
    const current = index === items.length - 1;
    return crumb(`${item.label}-${index}`, index === 0, !current && item.href ? <SiliconLink href={item.href} data-label={item.label} onClick={item.onClick}>{item.label}</SiliconLink>
      : !current && item.onClick ? <button type="button" data-label={item.label} onClick={item.onClick}>{item.label}</button>
      : <span aria-current={current ? "page" : undefined} data-label={item.label}>{item.label}</span>);
  });
  if (hidden.length) crumbs.splice(1, hidden.length, crumb("more", false, <DropdownMenuRoot>
    <DropdownMenuTrigger asChild><button type="button" className={styles.more} aria-label={`Show ${hidden.length} more ${hidden.length === 1 ? "level" : "levels"}`}><Ellipsis width={16} height={16} aria-hidden="true"/></button></DropdownMenuTrigger>
    <DropdownMenuContent align="start">{hidden.map((item, index) => item.href
      ? <DropdownMenuItem key={`${item.label}-${index + 1}`} asChild onClick={item.onClick}><SiliconLink href={item.href}>{item.label}</SiliconLink></DropdownMenuItem>
      : <DropdownMenuItem key={`${item.label}-${index + 1}`} disabled={!item.onClick} onClick={item.onClick}>{item.label}</DropdownMenuItem>)}
    </DropdownMenuContent>
  </DropdownMenuRoot>));
  return <nav aria-label={ariaLabel}><ol className={styles.list}><AnimatePresence mode="popLayout" initial={false}>{crumbs}</AnimatePresence></ol></nav>;
}

/* The gap between crumbs matches the gap inside one, so every chevron sits centered between its two labels. */
.list { position: relative; display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-hair) var(--space-related); margin: 0; padding: 0; list-style: none; }
.list li { display: inline-flex; align-items: center; gap: var(--space-related); color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); white-space: nowrap; }
.list li > svg { width: 16px; height: 16px; flex: 0 0 auto; color: var(--border-strong); stroke-width: 1.75; }
/* Each crumb reserves the width of its medium weight label, so becoming the current page never shifts the path. */
.list a, .list li > span, .list li > button { display: inline-flex; flex-direction: column; border-radius: var(--radius-detail); padding: var(--space-tight) var(--space-hair); }
.list a::after, .list li > span::after, .list li > button::after { height: 0; overflow: hidden; content: attr(data-label); font-weight: 500; visibility: hidden; user-select: none; pointer-events: none; }
.list li > button { border: 0; margin: 0; background: none; font: inherit; line-height: inherit; text-align: start; cursor: pointer; }
.list a, .list li > button { color: var(--text-secondary); text-decoration: underline 1px; text-decoration-color: transparent; text-underline-offset: 4px; transition: color var(--duration-fast) var(--ease-standard), text-decoration-color var(--duration-fast) var(--ease-standard); }
.list [aria-current="page"] { color: var(--accent-strong); font-weight: 500; transition: color var(--duration-fast) var(--ease-standard); }
/* The "…" of a collapsed path: a 24px square target, accented while its menu of hidden levels is open. */
.list .more { padding: var(--space-tight); }
.list .more svg { width: 16px; height: 16px; stroke-width: 1.75; }
.list .more[data-state="open"] { color: var(--accent-strong); }
@media (hover: hover) and (pointer: fine) { .list a:hover, .list li > button:hover { color: var(--accent-strong); text-decoration-color: color-mix(in oklab, currentColor 45%, transparent); } }
@media (prefers-reduced-motion: reduce) { .list a, .list li > button, .list [aria-current="page"] { transition: none; } }

"use client";

/**
 * Lets an app swap the link and image elements Silicon UI components render.
 *
 * Without a provider, Silicon UI renders a plain `<a>` and `<img>`, so components work in any React app (Vite, Remix, Astro,
 * plain React). Wrap the app once to use your framework's or your own components instead:
 *
 *   import Link from "next/link";
 *   import Image from "next/image";
 *   import { SiliconProvider } from "@/components/silicon-ui/lib/silicon-provider";
 *
 *   <SiliconProvider link={Link} image={Image}>{children}</SiliconProvider>
 *
 * Any component that accepts these props works, such as a locale-aware Link from next-intl or a React Router Link
 * wrapped to map `href` to `to`.
 */
import { createContext, createElement, useContext, useMemo, type AnchorHTMLAttributes, type ComponentType, type ImgHTMLAttributes, type ReactNode, type Ref } from "react";

/** The props Silicon UI passes to a link: an href plus ordinary anchor attributes. */
export interface SiliconLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  href: string;
  ref?: Ref<HTMLAnchorElement>;
}

/**
 * The props Silicon UI passes to an image. A subset of next/image's props, so next/image can be passed as is: either `fill`
 * (cover the positioned parent) or `width` and `height`, plus `sizes` and `priority` as hints.
 */
export interface SiliconImageProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "width" | "height" | "loading" | "srcSet"> {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  /** Fills the nearest positioned parent, like next/image's `fill`. */
  fill?: boolean;
  /** Loads the image eagerly with high priority, like next/image's `priority`. */
  priority?: boolean;
  loading?: "eager" | "lazy";
  ref?: Ref<HTMLImageElement>;
}

export type SiliconLinkComponent = ComponentType<SiliconLinkProps>;
export type SiliconImageComponent = ComponentType<SiliconImageProps>;

/** The default link: a plain anchor. */
export function SiliconAnchor(props: SiliconLinkProps) {
  return <a {...props} />;
}

const fillStyle = { position: "absolute", inset: 0, width: "100%", height: "100%" } as const;

/** The default image: a plain, lazily decoded `<img>` that understands `fill` and `priority`. */
export function SiliconImg({ alt, fill, priority, loading, style, ...props }: SiliconImageProps) {
  // eslint-disable-next-line @next/next/no-img-element -- the framework-free default; pass next/image through SiliconProvider instead.
  return <img alt={alt} decoding="async" {...props} loading={loading ?? (priority ? "eager" : "lazy")} fetchPriority={priority ? "high" : props.fetchPriority} style={fill ? { ...fillStyle, ...style } : style} />;
}

interface SiliconComponents {
  link: SiliconLinkComponent;
  image: SiliconImageComponent;
}

const SiliconContext = createContext<SiliconComponents>({ link: SiliconAnchor, image: SiliconImg });

export interface SiliconProviderProps {
  /** The link component Silicon UI renders for navigation, such as next/link or your own wrapped Link. Defaults to `<a>`. */
  link?: SiliconLinkComponent;
  /** The image component Silicon UI renders for photos, such as next/image. Defaults to `<img>`. */
  image?: SiliconImageComponent;
  children: ReactNode;
}

/** Sets the link and image components for every Silicon UI component inside it. Nested providers inherit what they do not set. */
export function SiliconProvider({ link, image, children }: SiliconProviderProps) {
  const parent = useContext(SiliconContext);
  const value = useMemo(() => ({ link: link ?? parent.link, image: image ?? parent.image }), [link, image, parent]);
  return <SiliconContext.Provider value={value}>{children}</SiliconContext.Provider>;
}

/** The link component from the nearest SiliconProvider, or a plain anchor. */
export const useArcLink = () => useContext(SiliconContext).link;
/** The image component from the nearest SiliconProvider, or a plain img. */
export const useArcImage = () => useContext(SiliconContext).image;

/** What Silicon UI components render for a link: the provider's link component, or a plain anchor. */
export function SiliconLink(props: SiliconLinkProps) {
  return createElement(useArcLink(), props);
}

/** What Silicon UI components render for an image: the provider's image component, or a plain img. */
export function SiliconImage(props: SiliconImageProps) {
  return createElement(useArcImage(), props);
}

"use client";

/**
 * Dropdown menu: a list of actions behind a trigger.
 *
 * Two ways to use it:
 *
 *   // Shorthand: a labelled trigger and a flat list.
 *   <DropdownMenu label="Manage silicon" items={[{ label: "Rename", onSelect: rename }, …]} />
 *
 *   // Composable (experimental): any trigger, labels, checked and radio items, shortcuts and submenus.
 *   <DropdownMenuRoot>
 *     <DropdownMenuTrigger asChild><Button variant="ghost" aria-label="Page options"><Ellipsis /></Button></DropdownMenuTrigger>
 *     <DropdownMenuContent align="end">
 *       <DropdownMenuLabel>Page</DropdownMenuLabel>
 *       <DropdownMenuItem icon={<Copy />} shortcut="⌘D" onSelect={duplicate}>Duplicate</DropdownMenuItem>
 *       <DropdownMenuCheckboxItem checked={wide} onCheckedChange={setWide}>Full width</DropdownMenuCheckboxItem>
 *       <DropdownMenuSub>
 *         <DropdownMenuSubTrigger icon={<FolderInput />}>Move to</DropdownMenuSubTrigger>
 *         <DropdownMenuSubContent>…</DropdownMenuSubContent>
 *       </DropdownMenuSub>
 *       <DropdownMenuSeparator />
 *       <DropdownMenuItem destructive icon={<Trash2 />} onSelect={remove}>Delete</DropdownMenuItem>
 *     </DropdownMenuContent>
 *   </DropdownMenuRoot>
 *
 * Every part shares one look: the same surface, the gliding highlight, the entrance that grows from the trigger.
 */
import { Fragment, cloneElement, forwardRef, isValidElement, useImperativeHandle, useLayoutEffect, useRef, useState } from "react";
import type { ComponentPropsWithoutRef, ReactNode, Ref } from "react";
import * as DropdownPrimitive from "@radix-ui/react-dropdown-menu";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { Check, ChevronDown, ChevronRight } from "lucide-react";
import { MenuHighlight, useMenuHighlight } from "../lib/menu-highlight";
import { motionTokens } from "../lib/motion-tokens";
import styles from "./dropdown-menu.module.css";

const ITEMS = '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"]';
const cx = (...names: Array<string | false | undefined>) => names.filter(Boolean).join(" ");

/** A menu surface's own ref, also handed to the caller's ref. It numbers the items in order, so their entrance
 *  staggers whatever groups and parts they sit in. */
function useSurfaceRef(forwarded: Ref<HTMLDivElement>) {
  const own = useRef<HTMLDivElement>(null);
  useImperativeHandle(forwarded, () => own.current as HTMLDivElement, []);
  useLayoutEffect(() => {
    own.current?.querySelectorAll<HTMLElement>(ITEMS).forEach((item, index) => item.style.setProperty("--i", String(index)));
  });
  return own;
}

/* ------------------------------------------------------------------------------------------------------------------ */
/* Composable parts                                                                                                    */
/* ------------------------------------------------------------------------------------------------------------------ */

/** The menu's state. Uncontrolled by default; pass `open` and `onOpenChange` to control it. */
export function DropdownMenuRoot(props: ComponentPropsWithoutRef<typeof DropdownPrimitive.Root>) {
  return <DropdownPrimitive.Root {...props} />;
}

export interface DropdownMenuTriggerProps extends ComponentPropsWithoutRef<typeof DropdownPrimitive.Trigger> {
  /** Render your own trigger (an icon-only Button with an aria-label, an avatar and name) instead of the default one. */
  asChild?: boolean;
}

/** What opens the menu. Without `asChild` it is the default outlined trigger with a chevron. */
export const DropdownMenuTrigger = forwardRef<HTMLButtonElement, DropdownMenuTriggerProps>(function DropdownMenuTrigger({ asChild, className, children, ...props }, ref) {
  if (asChild) return <DropdownPrimitive.Trigger {...props} ref={ref} asChild>{children}</DropdownPrimitive.Trigger>;
  return (
    <DropdownPrimitive.Trigger {...props} ref={ref} type="button" className={cx(styles.trigger, className)}>
      {children}
      <ChevronDown className={styles.chevron} size={15} strokeWidth={1.8} aria-hidden="true" />
    </DropdownPrimitive.Trigger>
  );
});

export interface DropdownMenuContentProps extends ComponentPropsWithoutRef<typeof DropdownPrimitive.Content> {
  /** Which side of the trigger it opens on (default bottom). */
  side?: "top" | "right" | "bottom" | "left";
  /** How it lines up with the trigger (default end). */
  align?: "start" | "center" | "end";
}

/** The menu itself. One highlight glides between items for the pointer and jumps instantly for the keyboard. */
export const DropdownMenuContent = forwardRef<HTMLDivElement, DropdownMenuContentProps>(function DropdownMenuContent({ className, children, side = "bottom", align = "end", sideOffset = 6, collisionPadding = 12, ...props }, ref) {
  const { highlight, contentProps } = useMenuHighlight(ITEMS);
  const surface = useSurfaceRef(ref);
  return (
    <DropdownPrimitive.Portal>
      <DropdownPrimitive.Content {...props} {...contentProps} ref={surface} side={side} align={align} sideOffset={sideOffset} collisionPadding={collisionPadding} loop className={cx(styles.menu, className)}>
        <MenuHighlight state={highlight} className={styles.highlight} />
        {children}
      </DropdownPrimitive.Content>
    </DropdownPrimitive.Portal>
  );
});

export interface DropdownMenuItemProps extends ComponentPropsWithoutRef<typeof DropdownPrimitive.Item> {
  /** A 16px icon before the label. */
  icon?: ReactNode;
  /** A keyboard shortcut hint after the label, such as "⌘D". Shown only; bind the keys yourself. */
  shortcut?: string;
  /** A destructive action (delete, remove): shown in the danger colour. */
  destructive?: boolean;
  /** Make your own element the item, such as a link: `<DropdownMenuItem asChild><a href="/q3">Q3 2026</a></DropdownMenuItem>`.
   *  Its children become the label, and Enter follows the link. */
  asChild?: boolean;
}

/** One action, or with `asChild` one link. */
export const DropdownMenuItem = forwardRef<HTMLDivElement, DropdownMenuItemProps>(function DropdownMenuItem({ icon, shortcut, destructive, asChild, className, children, ...props }, ref) {
  const content = (label: ReactNode) => <>
    {icon ? <span className={styles.icon} aria-hidden="true">{icon}</span> : null}
    <span className={styles.itemLabel}>{label}</span>
    {shortcut ? <kbd className={styles.shortcut}>{shortcut}</kbd> : null}
  </>;
  const own = asChild && isValidElement<{ children?: ReactNode }>(children) ? children : null;
  return (
    <DropdownPrimitive.Item {...props} ref={ref} asChild={!!own} className={cx(styles.item, destructive && styles.destructive, className)} data-tone={destructive ? "danger" : undefined}>
      {own ? cloneElement(own, undefined, content(own.props.children)) : content(children)}
    </DropdownPrimitive.Item>
  );
});

export interface DropdownMenuCheckboxItemProps extends ComponentPropsWithoutRef<typeof DropdownPrimitive.CheckboxItem> {
  /** A keyboard shortcut hint after the label. */
  shortcut?: string;
}

/** An on/off setting, such as "Full width". A check shows in the icon column while it is on. */
export const DropdownMenuCheckboxItem = forwardRef<HTMLDivElement, DropdownMenuCheckboxItemProps>(function DropdownMenuCheckboxItem({ shortcut, className, children, ...props }, ref) {
  return (
    <DropdownPrimitive.CheckboxItem {...props} ref={ref} className={cx(styles.item, className)}>
      <span className={styles.icon} aria-hidden="true"><DropdownPrimitive.ItemIndicator><Check size={16} strokeWidth={2} /></DropdownPrimitive.ItemIndicator></span>
      <span className={styles.itemLabel}>{children}</span>
      {shortcut ? <kbd className={styles.shortcut}>{shortcut}</kbd> : null}
    </DropdownPrimitive.CheckboxItem>
  );
});

/** One choice out of several (the current space, a sort order). Wrap DropdownMenuRadioItems in it. */
export const DropdownMenuRadioGroup = DropdownPrimitive.RadioGroup;

export interface DropdownMenuRadioItemProps extends ComponentPropsWithoutRef<typeof DropdownPrimitive.RadioItem> {
  /** A 16px icon or avatar before the label; the check shows at the end while this is the current choice. */
  icon?: ReactNode;
}

/** One of the choices in a DropdownMenuRadioGroup. The current choice shows a check at the end. */
export const DropdownMenuRadioItem = forwardRef<HTMLDivElement, DropdownMenuRadioItemProps>(function DropdownMenuRadioItem({ icon, className, children, ...props }, ref) {
  return (
    <DropdownPrimitive.RadioItem {...props} ref={ref} className={cx(styles.item, className)}>
      {icon ? <span className={styles.icon} aria-hidden="true">{icon}</span> : null}
      <span className={styles.itemLabel}>{children}</span>
      <span className={styles.indicator} aria-hidden="true"><DropdownPrimitive.ItemIndicator><Check size={16} strokeWidth={2} /></DropdownPrimitive.ItemIndicator></span>
    </DropdownPrimitive.RadioItem>
  );
});

/** A section heading inside the menu, such as "Spaces". Not focusable. */
export const DropdownMenuLabel = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<typeof DropdownPrimitive.Label>>(function DropdownMenuLabel({ className, ...props }, ref) {
  return <DropdownPrimitive.Label {...props} ref={ref} className={cx(styles.sectionLabel, className)} />;
});

/** A hairline between groups of items. */
export const DropdownMenuSeparator = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<typeof DropdownPrimitive.Separator>>(function DropdownMenuSeparator({ className, ...props }, ref) {
  return <DropdownPrimitive.Separator {...props} ref={ref} className={cx(styles.separator, className)} />;
});

/** Groups items for assistive technology, without visual change. */
export const DropdownMenuGroup = DropdownPrimitive.Group;

/** A nested menu: a DropdownMenuSubTrigger and its DropdownMenuSubContent. */
export const DropdownMenuSub = DropdownPrimitive.Sub;

export interface DropdownMenuSubTriggerProps extends ComponentPropsWithoutRef<typeof DropdownPrimitive.SubTrigger> {
  /** A 16px icon before the label. */
  icon?: ReactNode;
}

/** The item that opens a submenu (on hover, click, or the right arrow key). */
export const DropdownMenuSubTrigger = forwardRef<HTMLDivElement, DropdownMenuSubTriggerProps>(function DropdownMenuSubTrigger({ icon, className, children, ...props }, ref) {
  return (
    <DropdownPrimitive.SubTrigger {...props} ref={ref} className={cx(styles.item, styles.subTrigger, className)}>
      {icon ? <span className={styles.icon} aria-hidden="true">{icon}</span> : null}
      <span className={styles.itemLabel}>{children}</span>
      <ChevronRight className={styles.subChevron} size={15} strokeWidth={1.8} aria-hidden="true" />
    </DropdownPrimitive.SubTrigger>
  );
});

/** The submenu's own menu, opening beside its trigger. */
export const DropdownMenuSubContent = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<typeof DropdownPrimitive.SubContent>>(function DropdownMenuSubContent({ className, children, sideOffset = 6, collisionPadding = 12, ...props }, ref) {
  const { highlight, contentProps } = useMenuHighlight(ITEMS);
  const surface = useSurfaceRef(ref);
  return (
    <DropdownPrimitive.Portal>
      <DropdownPrimitive.SubContent {...props} {...contentProps} ref={surface} sideOffset={sideOffset} collisionPadding={collisionPadding} loop className={cx(styles.menu, className)}>
        <MenuHighlight state={highlight} className={styles.highlight} />
        {children}
      </DropdownPrimitive.SubContent>
    </DropdownPrimitive.Portal>
  );
});

/* ------------------------------------------------------------------------------------------------------------------ */
/* Shorthand                                                                                                           */
/* ------------------------------------------------------------------------------------------------------------------ */

export interface DropdownItem {
  /** The item's text. */
  label: string;
  /** Runs when the item is chosen. */
  onSelect?: () => void;
  /** Shown but not choosable. */
  disabled?: boolean;
  /** A 16px icon before the label. */
  icon?: ReactNode;
  /** A destructive action, shown in the danger colour. */
  destructive?: boolean;
  /** Draws a separator above this item. */
  separatorBefore?: boolean;
}

export interface DropdownMenuProps {
  /** The trigger's text; when it names the current choice, a new label rises in and the trigger springs to its width. */
  label: string;
  /** The actions, in order. */
  items: DropdownItem[];
  /** An icon before the trigger's text. */
  icon?: ReactNode;
}

/** A new trigger label rises in while the old one leaves, and the trigger width springs to the measured text instead of snapping. */
function TriggerLabel({ text }: { text: string }) {
  const reduced = useReducedMotion();
  const measure = useRef<HTMLSpanElement>(null);
  const measured = useRef<string | null>(null);
  const [size, setSize] = useState<{ width: number | "auto"; animate: boolean }>({ width: "auto", animate: false });
  useLayoutEffect(() => {
    const node = measure.current;
    if (!node) return;
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const current = node.textContent;
      // Only a text change morphs; the first measure and font swaps settle instantly.
      const animate = measured.current !== null && measured.current !== current;
      measured.current = current;
      setSize({ width: Math.ceil(entry.borderBoxSize?.[0]?.inlineSize ?? node.offsetWidth), animate });
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  return <motion.span className={styles.label} initial={false} animate={{ width: size.width }} transition={size.animate && !reduced ? motionTokens.spring.morph : { duration: 0 }}>
    <span ref={measure} className={styles.labelMeasure} aria-hidden="true">{text}</span>
    <AnimatePresence mode="popLayout" initial={false}>
      <motion.span key={text} className={styles.labelText} initial={reduced ? false : { opacity: 0, y: "0.3em", filter: `blur(${motionTokens.blur.soft}px)` }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: "-0.3em", filter: `blur(${motionTokens.blur.subtle}px)`, transition: { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] } }} transition={{ duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }}>{text}</motion.span>
    </AnimatePresence>
  </motion.span>;
}

/** The shorthand: a labelled trigger and a flat list of actions, built from the parts above. */
export function DropdownMenu({ label, items, icon }: DropdownMenuProps) {
  return (
    <DropdownMenuRoot>
      <DropdownMenuTrigger>
        {icon ? <span className={styles.triggerIcon} aria-hidden="true">{icon}</span> : null}
        <TriggerLabel text={label} />
      </DropdownMenuTrigger>
      <DropdownMenuContent>
        {items.map(item => (
          <Fragment key={item.label}>
            {item.separatorBefore ? <DropdownMenuSeparator /> : null}
            <DropdownMenuItem icon={item.icon} destructive={item.destructive} disabled={item.disabled} onSelect={item.onSelect}>{item.label}</DropdownMenuItem>
          </Fragment>
        ))}
      </DropdownMenuContent>
    </DropdownMenuRoot>
  );
}

export default DropdownMenu;

.trigger { display: inline-flex; max-width: 100%; min-height: var(--control-height-sm); align-items: center; gap: var(--space-related); padding: 0 var(--space-group); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); font-weight: 500; cursor: pointer; transition: background-color var(--duration-instant) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), box-shadow var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .trigger:hover { border-color: var(--border-strong); background: var(--surface-muted); box-shadow: var(--shadow-resting); } }
/* The trigger anchors the menu, so press feedback stays in color. A scaled rect would be measured on pointerdown and shift the menu. */
.trigger[data-state="open"] { border-color: var(--border-strong); background: var(--surface-muted); box-shadow: none; }
.trigger:active { border-color: var(--border-strong); background: color-mix(in oklab, var(--surface-muted), var(--border) 55%); box-shadow: none; }
.item:focus-visible { outline: none; }
